const e = $input.first().json;
const exec = e.execution ?? {};
const wf = e.workflow ?? {};
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const quando = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
const mensagem = exec.error?.message ?? 'Erro sem mensagem';
const no = exec.lastNodeExecuted ?? exec.error?.node?.name ?? 'desconhecido';
let html = '<h2>Erro no ' + esc(wf.name) + '</h2>';
html += '<p><b>Quando:</b> ' + esc(quando) + ' (Brasília)</p>';
html += '<p><b>Nó:</b> ' + esc(no) + '</p>';
html += '<p><b>Mensagem:</b> ' + esc(mensagem) + '</p>';
html += '<p><b>Execução:</b> ' + esc(exec.id) + ' (' + esc(exec.mode) + ')</p>';
if (exec.url) html += '<p><a href="' + esc(exec.url) + '">Abrir a execução no n8n</a></p>';
if (exec.error?.stack) html += '<pre style="font-size:12px;white-space:pre-wrap">' + esc(String(exec.error.stack).slice(0, 3000)) + '</pre>';
// Alertas iguais (mesmo nó e mesma mensagem, sem os números) saem no máximo um a cada 15 min.
// Os alertas de envio ao assessor já chegam deduplicados por item, então sempre saem.
const unico = no === 'Alertar falha de envio ao assessor';
const assinatura = (no + '|' + mensagem).replace(/\d+/g, '#').replace(/\s+/g, ' ').slice(0, 200);
const sufixo = unico ? 'exec:' + exec.id : assinatura + ':' + Math.floor(Date.now() / 900000);
const chave = 'concierge-alerta-erro:' + sufixo;
if (!unico) html += '<p style="color:#666">Alertas iguais a este nos próximos 15 minutos não serão enviados.</p>';

// Painel da corretora: o alerta em linguagem simples. As mensagens dos nós "Alertar…" e "Registrar falha…"
// são escritas para pessoas; nos demais erros, o texto técnico fica só para o suporte.
const CATALOGO = {
  'Registrar falha do agente': ['O Concierge não conseguiu responder um cliente', 'critico', 'atendimento', 'O suporte já foi avisado. Confira a conversa do cliente e, se preciso, peça para a equipe falar com ele.'],
  'Registrar falha na validação': ['O app do Concierge não respondeu ao confirmar um cliente', 'critico', 'atendimento', 'O suporte já foi avisado. Clientes que ainda não se identificaram podem não conseguir entrar até isso ser resolvido.'],
  'Alertar mensagem não entregue': ['Uma resposta do Concierge não chegou ao cliente', 'atencao', 'atendimento', 'Confira a conversa e veja se o cliente precisa de outro contato.'],
  'Alertar falha de envio ao assessor': ['Aviso de pedido ou resumo não enviado', 'atencao', 'pedidos', 'Confira o pedido na tela Pedidos e avise a central, se preciso.'],
  'Alertar campanha pausada': ['Campanha pausada: a Meta recusou o texto ou a conta', 'critico', 'envios', 'O suporte confere o modelo ou a conta na Meta. Depois, a campanha é retomada na tela Envios.'],
  'Alertar freio do enviador': ['Envio pausado por muitas falhas', 'atencao', 'envios', 'O suporte confere as falhas antes de retomar a campanha.'],
  'Alertar benefício não configurado': ['Aniversários sem presente definido', 'atencao', 'envios', 'Defina com o suporte o presente de aniversário de cada categoria.'],
  'Alertar qualidade do número': ['Qualidade do número em amarelo ou vermelho', 'atencao', 'envios', 'Reduza os envios de campanha até a qualidade voltar ao verde.'],
};
const nomeWf = String(wf.name ?? '');
const areaWf = /Campanhas/i.test(nomeWf) ? 'envios' : /Base de conhecimento/i.test(nomeWf) ? 'base' : /Agente/i.test(nomeWf) ? 'atendimento' : 'geral';
const TITULO_AREA = { envios: 'Erro técnico nos envios', base: 'Erro técnico na base de conhecimento', atendimento: 'Erro técnico no atendimento', geral: 'Erro técnico' };
const item = CATALOGO[no];
let gravidade = item ? item[1] : areaWf === 'atendimento' ? 'atencao' : 'info';
if (no === 'Alertar qualidade do número' && /RED|vermelh/i.test(mensagem)) gravidade = 'critico';
const painel = {
  chave: sufixo,
  tipo: item ? no : 'erro_tecnico',
  gravidade,
  area: item ? item[2] : areaWf,
  titulo: item ? item[0] : TITULO_AREA[areaWf],
  mensagem: item ? String(mensagem).slice(0, 500) : '',
  acao: item ? item[3] : 'O suporte técnico já foi avisado por e-mail.',
  workflow: nomeWf,
  no,
  execucao_id: String(exec.id ?? ''),
  execucao_url: String(exec.url ?? ''),
  detalhe: JSON.stringify({ mensagem: String(mensagem).slice(0, 2000), modo: exec.mode ?? null, pilha: exec.error?.stack ? String(exec.error.stack).slice(0, 3000) : null }),
};
return [{ json: { assunto: '[Agente Concierge] Erro em ' + no, html, chave, painel } }];
